import type { ReactNode } from "react";
import { InfoTooltip } from "@/components/ui/InfoTooltip";
import styles from "./history.module.css";
export function StatCard({
  label,
  icon,
  tint,
  value,
  suffix,
  tooltip,
  children,
}: {
  label: string;
  icon: ReactNode;
  tint: string;
  value: number;
  suffix?: ReactNode;
  tooltip: string;
  children: ReactNode;
}) {
  return (
    <div
      className={`hover-card backdrop-blur-xs [border:1px_solid_var(--h-border)] rounded-[var(--appearance-radius,_22px)] [background:var(--h-surface)] p-5.5 min-w-0`}
    >
      <div className="flex items-center gap-2.5 text-[var(--h-muted)] text-[14px] font-semibold">
        <span
          className={`${styles.tile} grid place-items-center w-8.5 h-8.5 rounded-[var(--appearance-radius,_11px)] shrink-0`}
          style={{ background: tint }}
        >
          {icon}
        </span>
        <span>{label}</span>
        <span className="ml-auto">
          <InfoTooltip
            className="history-surface"
            label={`About ${label}`}
            content={tooltip}
          />
        </span>
      </div>
      <p className="[margin:14px_0_8px] text-[44px] leading-[1.1] font-extrabold tracking-[-0.05em] [font-variant-numeric:tabular-nums]">
        {new Intl.NumberFormat("en").format(value)}
        {suffix}
      </p>
      {children}
    </div>
  );
}
